import os
from typing import List, Dict, Any, Optional

try:
    from google.cloud import texttospeech
except ImportError as e:
    raise ImportError(
        "google-cloud-texttospeech is required. Install with: pip install google-cloud-texttospeech"
    ) from e


def list_voices_for_locale(target_locale: str) -> List[Dict[str, Any]]:
    client = texttospeech.TextToSpeechClient()
    response = client.list_voices(language_code=target_locale)

    voices: List[Dict[str, Any]] = []
    for voice in response.voices:
        voices.append(
            {
                "name": voice.name,
                "language_codes": list(voice.language_codes),
                "ssml_gender": texttospeech.SsmlVoiceGender(voice.ssml_gender).name
                if voice.ssml_gender is not None
                else None,
                "natural_sample_rate_hertz": voice.natural_sample_rate_hertz,
            }
        )
    return voices


def select_voice_for_locale(target_locale: str, preferred_gender: Optional[str] = None) -> Dict[str, Any]:
    voices = list_voices_for_locale(target_locale)
    if not voices:
        raise ValueError(f"No voices available for locale: {target_locale}")

    if preferred_gender:
        preferred_gender = preferred_gender.strip().upper()
        for voice in voices:
            if voice["ssml_gender"] == preferred_gender:
                return voice

    return voices[0]


def synthesize_text(
    text: str,
    target_locale: str,
    output_path: str = "output.wav",
    preferred_gender: Optional[str] = None,
) -> Dict[str, Any]:
    voice = select_voice_for_locale(target_locale, preferred_gender=preferred_gender)

    client = texttospeech.TextToSpeechClient()
    synthesis_input = texttospeech.SynthesisInput(text=text)

    gender_enum = texttospeech.SsmlVoiceGender[voice["ssml_gender"]] if voice["ssml_gender"] else texttospeech.SsmlVoiceGender.SSML_VOICE_GENDER_UNSPECIFIED

    voice_params = texttospeech.VoiceSelectionParams(
        language_code=target_locale,
        name=voice["name"],
        ssml_gender=gender_enum,
    )

    audio_config = texttospeech.AudioConfig(
        audio_encoding=texttospeech.AudioEncoding.LINEAR16
    )

    response = client.synthesize_speech(
        input=synthesis_input,
        voice=voice_params,
        audio_config=audio_config,
    )

    with open(output_path, "wb") as out:
        out.write(response.audio_content)

    return {
        "selected_voice": voice,
        "output_path": os.path.abspath(output_path),
    }
